actions.script:
let decoded = {}
try { if (typeof findJson === 'string' && findJson.length <= 8192) decoded = JSON.parse(findJson) || {} } catch (err) { decoded = {} }
findMap = {}
if (!Array.isArray(decoded) && typeof decoded === 'object') {
    // the find parameters of Commons/Tasks/List.xml (its keepJson), and its smart lists
    for (const key of ['list', 'text', 'statusId', 'purposeEnumId', 'rootWorkEffortId', 'recordId', 'orderByField', 'pageIndex',
            'due_period', 'due_poffset', 'due_pdate', 'due_from', 'due_thru']) {
        const value = decoded[key]
        if (typeof value === 'string' || typeof value === 'number') findMap[key] = String(value)
    }
    if (findMap.list && !['all', 'today', 'week', 'overdue', 'assigned', 'created', 'watching', 'done'].includes(findMap.list)) delete findMap.list
}
findJson = Object.keys(findMap).length ? JSON.stringify(findMap) : null

found = false; visible = false; workEffort = null; roleList = []
isOwner = false; isAssignee = false; isWatcher = false; isParty = false; canUpdate = false; isMember = false; canManage = false
const notAvailable = () => ec.resource.expand('Task ${workEffortId} is not available', '', {workEffortId: workEffortId})
const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (row == null || row.workEffortTypeEnumId !== 'WetTask') {
    if (need !== 'check') ec.message.addError(notAvailable())
    return
}
// a confidential issue's task (Smithy) that the user is no Owner of is as a task that does not exist, whatever the role
// on its project and for its own parties too (projects/HiddenItems.js; Mantle's get#VisibleProjectInfo hiddenItemIds)
if (!ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').shown(workEffortId)) {
    if (need !== 'check') ec.message.addError(notAvailable())
    return
}
// a production run's operation (a WetTask whose root or parent is a WepProductionRun, impl-manufacturing F38) is
// shop-floor work, changed only through Manufacturing's production services: no work item in Projects, and
// read only in Commons
const productionRun = (id) => !!id && ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id)
        .selectField('purposeEnumId').disableAuthz().one()?.purposeEnumId === 'WepProductionRun'
const production = row.purposeEnumId === 'WepProductionRun' || productionRun(row.rootWorkEffortId)
        || (row.parentWorkEffortId !== row.rootWorkEffortId && productionRun(row.parentWorkEffortId))
if (production && app === 'projects') {
    if (need !== 'check') ec.message.addError(notAvailable())
    return
}
// a maintenance work order and its steps (managed work, impl-maintenance P3) are no task here: they are worked from
// their work order in Maintenance, and the generic task services refuse them (MANAGED_WORK)
if (ec.resource.script('component://mr-mantle/service/mantle/work/WorkProcesses.js').managedIds([workEffortId]).length) {
    if (need !== 'check') ec.message.addError(ec.resource.expand('MANAGED_WORK: Work ${workEffortId} is a maintenance work order\'s; open it in Maintenance (/qapps/Maintenance/WorkOrders/WorkOrderDetail?workEffortId=${rootId})', '',
            {workEffortId: workEffortId, rootId: row.rootWorkEffortId || workEffortId}))
    return
}
found = true
// Projects: the project's visibility first (get#VisibleProjectInfo, impl-projects.md F1)
let projectVisible = false
let projectInfo = null
if (app === 'projects' && row.rootWorkEffortId) {
    projectInfo = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
    const ids = (name) => Array.from(projectInfo[name] || [])
    projectVisible = !!projectInfo.allProjects || (ids('visibleProjectIds').includes(row.rootWorkEffortId)
            && (!['WevRestricted', 'WevConfidential'].includes(row.visibilityEnumId) || ids('managedProjectIds').includes(row.rootWorkEffortId)
                || ids('restrictedItemIds').includes(workEffortId)))
    // a client contact: an item shared with it only (impl-projects.md P10)
    if (projectInfo.itemVisibilityIds && !ids('itemVisibilityIds').includes(row.visibilityEnumId)) projectVisible = false
}
const info = projectVisible ? {recordVisible: true} : ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo').parameters({
    recordEntityName: 'mantle.work.effort.WorkEffort', recordId: workEffortId, checkOnly: true}).call()
if (ec.message.hasError()) return
visible = info?.recordVisible === true
if (!visible) {
    ec.logger.info(`Task ${workEffortId} is not visible to user ${ec.user.userId}: ${info?.notVisibleReason || ''}`)
    if (need !== 'check') ec.message.addError(notAvailable())
    return
}
workEffort = row.getMap()
const partyId = ec.user.userAccount?.partyId || null
const cf = ec.entity.conditionFactory
if (partyId) {
    for (const wep of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', workEffortId).condition('partyId', partyId)
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null))
            .condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true)).list()) {
        if (!roleList.includes(wep.roleTypeId)) roleList.push(wep.roleTypeId)
    }
}
isOwner = !!partyId && row.ownerPartyId === partyId
isAssignee = roleList.includes('Assignee')
isParty = roleList.length > 0
isWatcher = roleList.includes('Watcher') || ec.entity.find('mantle.party.communication.RecordFollower')
        .condition('recordEntityName', 'mantle.work.effort.WorkEffort').condition('recordId', workEffortId)
        .condition('userId', ec.user.userId).count() > 0
canUpdate = isOwner || isAssignee
if (app === 'projects' && row.rootWorkEffortId) {
    if (!projectInfo) projectInfo = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
    const clientRoles = ['Customer', 'CustomerBillTo', 'ClientManager', 'ClientBilling']
    isMember = !!partyId && ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', row.rootWorkEffortId)
            .condition('partyId', partyId).condition(cf.makeConditionDate('fromDate', 'thruDate', null))
            .condition(cf.makeCondition('roleTypeId', 'not-in', clientRoles)).count() > 0
    canManage = !!projectInfo.allProjects || Array.from(projectInfo.managedProjectIds || []).includes(row.rootWorkEffortId)
            || (projectVisible && ec.user.isInGroup('BOSS_PROJECT_MANAGER'))
    canUpdate = canUpdate || isMember || canManage || roleList.includes('Manager')
    // a client contact changes nothing (impl-projects.md P10; P10b opens its messages)
    if (projectInfo.isClient) {
        isMember = false; canManage = false; canUpdate = false
        // and no cost of it (design-projects.md §1.1)
        for (const field of ['actualCost', 'actualClientCost', 'totalClientCostAllowed', 'costUomId']) delete workEffort[field]
    }
}
const closedProject = row.rootWorkEffortId && ec.entity.find('mantle.work.effort.WorkEffort')
        .condition('workEffortId', row.rootWorkEffortId).one()?.statusId === 'WeClosed'
if (closedProject) canUpdate = false
if (production) {
    canUpdate = false
    // and no cost of it: the task roll-up writes the operation's cost at pay rates (F36)
    for (const field of ['actualCost', 'actualClientCost', 'totalClientCostAllowed', 'costUomId']) delete workEffort[field]
    if (need === 'update') ec.message.addError(ec.resource.expand('Operation ${workEffortId} is production work: record it on the shop floor in Manufacturing', '', {workEffortId: workEffortId}))
    return
}
if (need === 'update' && closedProject) {
    ec.message.addError(ec.l10n.localize('PROJECT_CLOSED: The project is closed; reopen it before changing its work or plan'))
    return
}
if (need === 'update' && !canUpdate)
    ec.message.addError(ec.resource.expand('You may not change task ${workEffortId}', '', {workEffortId: workEffortId}))

const lists = ['all', 'today', 'week', 'overdue', 'assigned', 'created', 'watching', 'done']
if (!lists.includes(list)) list = 'all'
rowList = []; rowCount = 0; pageMaxIndex = 0; pageRangeLow = 0; pageRangeHigh = 0
counts = {}
for (const key of lists) counts[key] = 0
const partyId = ec.user.userAccount?.partyId || null
if (!partyId) return
const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
const nowMillis = toMillis(ec.user.nowTimestamp)
const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
const dayStart = (text) => toMillis(ec.l10n.parseTimestamp(text + ' 00:00:00.000', pattern))
// a day is 23 to 25 hours, so 30 hours after its start is in the next one
const nextDay = (text) => dayText(dayStart(text) + 30 * 3600000)
const todayText = dayText(nowMillis)
const todayStart = dayStart(todayText)
const tomorrowStart = dayStart(nextDay(todayText))
let weekText = todayText
for (let i = 0; i < 7; i++) weekText = nextDay(weekText)
const weekEnd = dayStart(weekText)

// the slice: the user's rows, the tasks owned, the tasks followed; never a confidential issue's task the user is no
// Owner of (projects/HiddenItems.js)
const hiddenItems = ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js')
const hiddenIds = hiddenItems.ids()
const entries = new Map()
const entryOf = (id) => {
    let entry = entries.get(id)
    if (!entry) { entry = {roles: new Set(), snoozedThru: null, follower: false, row: null}; entries.set(id, entry) }
    return entry
}
for (const wep of ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('partyId', partyId)
        .condition('workEffortTypeEnumId', 'WetTask').condition(cf.makeConditionDate('fromDate', 'thruDate', null))
        .condition(cf.makeCondition('partyStatusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true)).list()) {
    if (hiddenIds.has(wep.workEffortId)) continue
    const entry = entryOf(wep.workEffortId)
    entry.roles.add(wep.roleTypeId)
    const snoozedThru = toMillis(wep.snoozedThruDate)
    if (snoozedThru != null && (entry.snoozedThru == null || snoozedThru > entry.snoozedThru)) entry.snoozedThru = snoozedThru
    if (!entry.row) entry.row = wep
}
for (const owned of ec.entity.find('mantle.work.effort.WorkEffort').condition('ownerPartyId', partyId)
        .condition('workEffortTypeEnumId', 'WetTask').list()) {
    if (hiddenIds.has(owned.workEffortId)) continue
    const entry = entryOf(owned.workEffortId)
    entry.row = owned
}
const followed = Array.from(ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', 'mantle.work.effort.WorkEffort')
        .condition('userId', ec.user.userId).list()).map((follower) => follower.recordId)
for (const id of followed) {
    if (hiddenIds.has(id)) continue
    if (entries.has(id)) { entries.get(id).follower = true; continue }
    // a task followed and not otherwise the user's: only while the user may see it
    const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).one()
    if (task == null || task.workEffortTypeEnumId !== 'WetTask') continue
    const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo').parameters({
        recordEntityName: 'mantle.work.effort.WorkEffort', recordId: id, checkOnly: true}).call()
    if (info?.recordVisible !== true) continue
    const entry = entryOf(id)
    entry.row = task
    entry.follower = true
}

const openOf = (row) => !['WeComplete', 'WeClosed', 'WeCancelled'].includes(row.statusId)
const doneOf = (row) => ['WeComplete', 'WeClosed'].includes(row.statusId)
const dueOf = (row) => toMillis(row.estimatedCompletionDate) ?? toMillis(row.estimatedStartDate)
// each smart list: its status part (open or done) and the rest
const rest = {
    all: () => true,
    today: (row, entry) => { const due = dueOf(row); return due != null && due >= todayStart && due < tomorrowStart && !(entry.snoozedThru != null && entry.snoozedThru > nowMillis) },
    week: (row) => { const due = dueOf(row); return due != null && due >= todayStart && due < weekEnd },
    overdue: (row) => { const due = dueOf(row); return due != null && due < todayStart },
    assigned: (row, entry) => entry.roles.has('Assignee'),
    created: (row) => row.ownerPartyId === partyId,
    watching: (row, entry) => entry.roles.has('Watcher') || entry.follower,
    done: () => true
}
const statusPart = (key) => key === 'done' ? doneOf : openOf
// a protected People task (offboarding, an equipment return) only for an assignee who is not the person it is about
// (Mantle's Checklists.js hiddenTaskIds; impl-people P7 review, F22): the holder of a return task's equipment does not list it
// (P21: a task linked to a confidential case too, Mantle's PeopleCases.js protectedTaskIds)
const sliceIds = Array.from(entries.keys())
if (sliceIds.length && ec.resource.script('component://mr-mantle/service/mantle/request/PeopleCases.js').protectedTaskIds(sliceIds).length > 0)
    for (const id of ec.resource.script('component://mr-mantle/service/mantle/humanres/Checklists.js').hiddenTaskIds(sliceIds, partyId))
        entries.delete(id)
const all = Array.from(entries.entries()).filter(([id, entry]) => entry.row != null).map(([id, entry]) => ({id: id, entry: entry, row: entry.row}))
for (const key of lists) counts[key] = all.filter((item) => statusPart(key)(item.row) && rest[key](item.row, item.entry)).length

// the find
const statusIds = statusId ? String(statusId).split(',').map((id) => id.trim()).filter((id) => id) : []
const words = text ? String(text).trim().toLowerCase() : ''
const fromMillis = toMillis(dueFrom)
const thruMillis = toMillis(dueThru)
let linked = null
if (recordId) {
    linked = new Set()
    const recordText = String(recordId).trim()
    for (const link of ec.entity.find('mantle.request.RequestWorkEffort').condition('requestId', recordText).list()) linked.add(link.workEffortId)
    for (const link of ec.entity.find('mantle.work.effort.WikiPageWorkEffort').condition('wikiPageId', recordText).list()) linked.add(link.workEffortId)
    for (const link of ec.entity.find('mantle.work.effort.WorkEffortRecord').condition('recordId', recordText).list()) linked.add(link.workEffortId)
}
let rows = all.filter((item) => {
    const row = item.row
    if (statusIds.length ? !statusIds.includes(row.statusId) : !statusPart(list)(row)) return false
    if (!rest[list](row, item.entry)) return false
    if (purposeEnumId && row.purposeEnumId !== purposeEnumId) return false
    if (rootWorkEffortId && row.rootWorkEffortId !== rootWorkEffortId) return false
    if (linked && !linked.has(item.id)) return false
    if (fromMillis != null || thruMillis != null) {
        const due = dueOf(row)
        if (due == null || (fromMillis != null && due < fromMillis) || (thruMillis != null && due >= thruMillis)) return false
    }
    if (words && !(String(row.workEffortName || '').toLowerCase().includes(words) || String(row.description || '').toLowerCase().includes(words)
            || String(item.id).toLowerCase().includes(words))) return false
    return true
})

// the order: a column's, else by due (none last), priority and name; Done by completion, the latest first
const sortKey = orderByField ? String(orderByField).replace(/^[+^]/, '') : ''
const desc = sortKey.startsWith('-')
const field = desc ? sortKey.substring(1) : sortKey
const byText = (left, right) => String(left.row.workEffortName || '').localeCompare(String(right.row.workEffortName || ''))
const byDue = (left, right) => (dueOf(left.row) ?? Number.MAX_SAFE_INTEGER) - (dueOf(right.row) ?? Number.MAX_SAFE_INTEGER)
const byPriority = (left, right) => (left.row.priority ?? 99) - (right.row.priority ?? 99)
const comparators = {
    workEffortName: byText, workEffortId: (left, right) => String(left.id).localeCompare(String(right.id)),
    estimatedCompletionDate: (left, right) => byDue(left, right) || byPriority(left, right) || byText(left, right),
    priority: (left, right) => byPriority(left, right) || byDue(left, right) || byText(left, right),
    statusId: (left, right) => String(left.row.statusId || '').localeCompare(String(right.row.statusId || '')) || byDue(left, right)
}
if (comparators[field]) {
    rows.sort(comparators[field])
    if (desc) rows.reverse()
} else if (list === 'done') {
    const doneAt = (item) => toMillis(item.row.actualCompletionDate) ?? toMillis(item.row.lastUpdatedStamp) ?? 0
    rows.sort((left, right) => doneAt(right) - doneAt(left) || byText(left, right))
} else {
    rows.sort((left, right) => byDue(left, right) || byPriority(left, right) || byText(left, right))
}

rowCount = rows.length
const size = pageNoLimit ? Math.max(1, rowCount) : Math.max(1, Math.min(Number(pageSize) || 25, 200))
pageSize = size
pageMaxIndex = rowCount ? Math.floor((rowCount - 1) / size) : 0
pageIndex = Math.min(Math.max(0, Number(pageIndex) || 0), pageMaxIndex)
const page = rows.slice(pageIndex * size, (pageIndex + 1) * size)
pageRangeLow = rowCount ? pageIndex * size + 1 : 0
pageRangeHigh = Math.min((pageIndex + 1) * size, rowCount)
const entryMap = {}
for (const item of page) entryMap[item.id] = {roles: Array.from(item.entry.roles), snoozedThru: item.entry.snoozedThru, follower: item.entry.follower}
rowList = ec.service.sync().name('ironstone.commons.TaskServices.decorate#TaskRows').parameters({taskList: page.map((item) => item.row.getMap ? item.row.getMap() : item.row),
    entries: entryMap}).call()?.rowList || []

rowList = []
const tasks = Array.from(taskList || [])
if (!tasks.length) return
const cf = ec.entity.conditionFactory
const L = (text) => ec.l10n.localize(text)
const partyId = ec.user.userAccount?.partyId || null
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
const nowMillis = toMillis(ec.user.nowTimestamp)
const fmt = (millis, format) => ec.l10n.format(new Date(Number(millis)), format)
const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
const dayStart = (text) => toMillis(ec.l10n.parseTimestamp(text + ' 00:00:00.000', pattern))
const todayText = dayText(nowMillis)
const todayStart = dayStart(todayText)
const tomorrowStart = dayStart(dayText(todayStart + 30 * 3600000))
const thisYear = fmt(nowMillis, 'yyyy')
const ids = tasks.map((task) => task.workEffortId)

// the user's roles, snooze and follow when not given
const mine = {}
if (entries) Object.keys(entries).forEach((id) => { mine[id] = entries[id] })
const missing = ids.filter((id) => !mine[id])
if (missing.length && partyId) {
    for (const id of missing) mine[id] = {roles: [], snoozedThru: null, follower: false}
    for (const wep of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', 'in', missing).condition('partyId', partyId)
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null))
            .condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true)).list()) {
        const entry = mine[wep.workEffortId]
        if (!entry.roles.includes(wep.roleTypeId)) entry.roles.push(wep.roleTypeId)
        const snoozedThru = toMillis(wep.snoozedThruDate)
        if (snoozedThru != null && (entry.snoozedThru == null || snoozedThru > entry.snoozedThru)) entry.snoozedThru = snoozedThru
    }
    for (const follower of ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', 'mantle.work.effort.WorkEffort')
            .condition('recordId', 'in', missing).condition('userId', ec.user.userId).list()) mine[follower.recordId].follower = true
}

const statusIds = Array.from(new Set(tasks.map((task) => task.statusId).filter((id) => id)))
const colors = ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors').parameters({statusIdList: statusIds}).call()?.colors || {}
const statusLabel = (id) => {
    const item = id ? ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one() : null
    return item ? (item.description || id) : (id || '')
}
const enumLabel = (id) => {
    const item = id ? ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one() : null
    return item ? (item.description || id) : (id || '')
}
const partyName = (party) => party ? (party.organizationName || [party.firstName, party.lastName].filter((name) => name).join(' ') ||
        party.pseudoId || party.partyId) : null

// the projects
const projectIds = Array.from(new Set(tasks.map((task) => task.rootWorkEffortId).filter((id) => id)))
const projects = {}
if (projectIds.length) for (const project of ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', projectIds).list())
    projects[project.workEffortId] = project.workEffortName || project.workEffortId
// the production runs among the roots and parents: a run's operation is no task to change (impl-manufacturing F38)
const aboveIds = Array.from(new Set(projectIds.concat(tasks.map((task) => task.parentWorkEffortId).filter((id) => id))))
const productionRunIds = new Set(aboveIds.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', aboveIds)
        .condition('purposeEnumId', 'WepProductionRun').selectField('workEffortId').disableAuthz().list()).map((run) => run.workEffortId) : [])
// managed work (a maintenance work order and its steps, impl-maintenance P3) is no task to change here
const managedIds = new Set(ec.resource.script('component://mr-mantle/service/mantle/work/WorkProcesses.js').managedIds(ids))
// the assignees
const assignees = {}
const assigneeParties = new Set()
for (const wep of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', 'in', ids).condition('roleTypeId', 'Assignee')
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null))
        .condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true)).list()) {
    const list = assignees[wep.workEffortId] || (assignees[wep.workEffortId] = [])
    if (!list.includes(wep.partyId)) list.push(wep.partyId)
    assigneeParties.add(wep.partyId)
}
const names = {}
if (assigneeParties.size) for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', Array.from(assigneeParties)).list())
    names[party.partyId] = party.privateOwnerUserId && party.privateOwnerUserId !== ec.user.userId ? party.partyId : partyName(party)
// the record each task is on: the own joins, then the generic link
const links = {}
const addLink = (id, recordEntityName, recordId) => { if (!links[id]) links[id] = {recordEntityName: recordEntityName, recordId: recordId} }
for (const link of ec.entity.find('mantle.request.RequestWorkEffort').condition('workEffortId', 'in', ids).list())
    addLink(link.workEffortId, 'mantle.request.Request', link.requestId)
for (const link of ec.entity.find('mantle.work.effort.WikiPageWorkEffort').condition('workEffortId', 'in', ids).list())
    addLink(link.workEffortId, 'moqui.resource.wiki.WikiPage', link.wikiPageId)
for (const link of ec.entity.find('mantle.work.effort.WorkEffortRecord').condition('workEffortId', 'in', ids).orderBy('linkedDate').list())
    addLink(link.workEffortId, link.recordEntityName, link.recordId)
const captions = {}
const captionOf = (link) => {
    const key = link.recordEntityName + '|' + link.recordId
    if (key in captions) return captions[key]
    let caption = link.recordId
    let url = null
    try {
        const info = ec.service.sync().name('ironstone.shared.ChatterServices.get#RecordInfo').parameters({recordEntityName: link.recordEntityName,
            recordId: link.recordId}).call()
        if (ec.message.hasError()) ec.message.clearErrors()
