const todayText = ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
const tomorrowStart = toMillis(ec.l10n.parseTimestamp(ec.l10n.format(String(toMillis(ec.l10n.parseTimestamp(todayText + ' 00:00:00.000',
