const actions = ['complete', 'reassign', 'setDue', 'setPriority', 'moveToProject']
if (!actions.includes(action)) { ec.message.addError(ec.resource.expand('${action} is not a bulk action', '', {action: action})); return }
if (!ids.length) { ec.message.addError(ec.l10n.localize('Select one or more tasks first')); return }
if (action === 'reassign' && !assignToPartyId) { ec.message.addError(ec.l10n.localize('Choose who to assign them to')); return }
