            else if (action === 'setDue') call = ['ironstone.commons.TaskServices.update#TaskField', {workEffortId: id, field: 'due', value: dueDate || ''}]
            else if (action === 'setPriority') call = ['ironstone.commons.TaskServices.update#TaskField', {workEffortId: id, field: 'priority', value: priority}]
            else call = ['mantle.work.TaskServices.update#Task', {workEffortId: id, rootWorkEffortId: rootWorkEffortId || null}]
            ec.service.sync().name(call[0]).parameters(call[1]).requireNewTransaction(true).call()
