    ec.service.sync().name('create#mantle.work.effort.WorkEffortRecord').parameters({workEffortId: newWorkEffortId,
        recordEntityName: link.recordEntityName, recordId: link.recordId, linkedByUserId: ec.user.userId, linkedDate: ec.user.nowTimestamp}).call()

const refuse = (why) => ec.message.addError(ec.resource.expand('Task ${workEffortId} has ${why}, so it is not deleted: cancel it instead', '',
        {workEffortId: workEffortId, why: ec.l10n.localize(why)}))
const count = (entityName, field) => ec.entity.find(entityName).condition(field || 'workEffortId', workEffortId).count()
if (count('mantle.work.time.TimeEntry')) return refuse('time logged')
if (count('mantle.work.effort.WorkEffort', 'parentWorkEffortId') || count('mantle.work.effort.WorkEffort', 'rootWorkEffortId')) return refuse('sub-tasks')
if (count('mantle.work.effort.WorkEffortCommEvent')) return refuse('comments')
if (count('mantle.work.effort.WorkEffortContent')) return refuse('files')
// the links and followers are only links
const removeAll = (entityName, conditions) => {
    for (const row of ec.entity.find(entityName).condition(conditions).list())
        ec.service.sync().name('delete#' + entityName).parameters(row.getPrimaryKeys()).call()
}
removeAll('mantle.work.effort.WorkEffortRecord', {workEffortId: workEffortId})
removeAll('mantle.request.RequestWorkEffort', {workEffortId: workEffortId})
removeAll('mantle.work.effort.WikiPageWorkEffort', {workEffortId: workEffortId})
removeAll('mantle.party.communication.RecordFollower', {recordEntityName: 'mantle.work.effort.WorkEffort', recordId: workEffortId})
removeAll('mantle.work.effort.WorkEffortRecord', {recordEntityName: 'mantle.work.effort.WorkEffort', recordId: workEffortId})
if (ec.message.hasError()) return
ec.service.sync().name('mantle.work.WorkEffortServices.delete#WorkEffort').parameters({workEffortId: workEffortId, deleteWorkEffortParties: true}).call()
if (ec.message.hasError()) return
message = ec.resource.expand('Deleted: ${name}', '', {name: access.workEffort.workEffortName || workEffortId})
